'use strict';
const $=id=>document.getElementById(id),clamp=v=>Math.max(0,Math.min(250,Math.round(v)));
const onBoard=document.documentElement.dataset.source==='esp32';
let monitorMode=false;
let speed=0,revision=0,busy=false,offline=false;
let actualSpeed=0,engineRunning=false,braking=false,coolant=30,simTime=0,lastTick=Date.now();
const overrides={};
const flags={key:false,winker:false,check:false,abs:false,tcs:false};
function values(){const load=actualSpeed/250;return {speed:actualSpeed,rpm:engineRunning?1200+load*13800:0,ect:coolant,iat:30+load*20,map:20+load*81.3,tps:.6+load*2.9,o2:engineRunning?.8+Math.sin(simTime*2)*.2:0,afr:14.7,battery:engineRunning?13.8:12.6,ref1:5,ref2:5,rear:actualSpeed,...flags,...overrides};}
function render(data=values()){
 if(monitorMode)return;
 $('speed').textContent=String(Math.round(data.speed)).padStart(3,'0');$('rpm').textContent=Math.round(data.rpm).toLocaleString('en-US');$('ect').textContent=Math.round(data.ect);
 for(const [id,key,precision] of [['iat','iat',0],['map','map',1],['tps','tps',2],['o2','o2',2],['afr','afr',1],['absO2','o2',2],['absTps','tps',2],['absRpm','rpm',0],['rear','rear',0]])$(id).textContent=data[key].toFixed(precision);
 for(const key of ['ref1','ref2','battery'])$(key).textContent=data[key].toFixed(2)+' V';
 $('rpmFill').style.width=(data.rpm/15000*100)+'%';$('rearFill').style.width=(data.rear/250*100)+'%';
 $('needle').setAttribute('transform',`rotate(${data.speed/250*180} 200 205)`);
 $('knobFace').style.transform=`rotate(${-135+speed/250*270}deg)`;$('knobValue').textContent=`${speed} km/h`;
 $('knob').setAttribute('aria-valuenow',String(speed));$('knob').setAttribute('aria-valuetext',`${speed} kilometers per hour`);
 $('knob').setAttribute('aria-disabled',String(braking));$('increase').disabled=braking;$('decrease').disabled=braking;
 $('engineButton').textContent=engineRunning?'Stop Engine':'Start Engine';$('engineButton').setAttribute('aria-pressed',String(engineRunning));
 $('brakeButton').disabled=!engineRunning;$('brakeButton').textContent=braking?'Release Brake':'Brake';$('brakeButton').setAttribute('aria-pressed',String(braking));
 $('engineState').textContent=!engineRunning?'Engine off':braking?(actualSpeed>.1?'Braking':'Brake applied'):actualSpeed>.1?'Engine running':'Engine idling';
 for(const b of document.querySelectorAll('[data-status]'))b.setAttribute('aria-pressed',String(flags[b.dataset.status]));
 $('connection').textContent=offline?'CONNECTION LOST':onBoard?'ESP32 · SIMULATION':'SIMULATED DATA';$('connection').classList.toggle('offline',offline);
 $('notice').textContent=offline?'ESP32 connection lost. Controls continue as a local simulation.':onBoard?'Simulation only. ESP32 hosts this dashboard; no testbench connected.':'Simulation only. No testbench or ESP32 is connected.';
}
function setSpeed(value){if(braking)return;speed=clamp(value);revision++;render();sync();}
function toggleEngine(){engineRunning=!engineRunning;flags.key=engineRunning;braking=false;if(!engineRunning){actualSpeed=0;speed=0;}revision++;render();sync();}
function toggleBrake(){if(!engineRunning)return;braking=!braking;if(braking)speed=0;revision++;render();sync();}
function step(dt){dt=Math.max(0,Math.min(dt,.5));simTime+=dt;if(engineRunning){const target=braking?0:speed;const rate=braking?80:target>actualSpeed?18:30;const difference=target-actualSpeed;actualSpeed=Math.max(0,Math.min(250,actualSpeed+Math.sign(difference)*Math.min(Math.abs(difference),rate*dt)));coolant+=(75+actualSpeed/250*15-coolant)*.02*dt;}else{actualSpeed=0;coolant+=(30-coolant)*.015*dt;}render();}
function reset(){speed=0;actualSpeed=0;engineRunning=false;braking=false;coolant=30;simTime=0;for(const k in overrides)delete overrides[k];for(const k in flags)flags[k]=false;revision++;render();sync();}
async function sync(){
 if(monitorMode||!onBoard||busy)return;busy=true;const requestedRevision=revision;
 const query=new URLSearchParams({scenario:'manual',...values()});for(const k in flags)query.set(k,flags[k]?'1':'0');
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),2000);
 try{const response=await fetch('/api/telemetry?'+query,{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('Request failed');const data=await response.json();
 for(const [k,a,b] of [['speed',0,250],['rpm',0,15000],['ect',20,100]])if(typeof data[k]!=='number'||!Number.isFinite(data[k])||data[k]<a||data[k]>b)throw Error('Invalid telemetry');
 if(revision===requestedRevision){offline=false;render();}
 }catch{offline=true;render();}finally{clearTimeout(timer);busy=false;}
}
let ticks='';for(let i=0;i<=25;i++){const a=Math.PI+i/25*Math.PI,p=r=>[200+Math.cos(a)*r,205+Math.sin(a)*r],x=p(165),y=p(i%5===0?149:157);ticks+=`<line x1="${x[0]}" y1="${x[1]}" x2="${y[0]}" y2="${y[1]}" stroke="#8199b5" stroke-width="2"/>`;if(i%5===0){const t=p(130);ticks+=`<text x="${t[0]}" y="${t[1]+5}" text-anchor="middle" fill="#aebdd0" font-size="14">${i*10}</text>`;}}$('ticks').innerHTML=ticks;
const knob=$('knob');let drag=null;
knob.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;drag={y:e.clientY,value:speed};knob.setPointerCapture(e.pointerId);knob.focus();});
knob.addEventListener('pointermove',e=>{if(drag)setSpeed(drag.value+(drag.y-e.clientY)*1.5);});
for(const event of ['pointerup','pointercancel','lostpointercapture'])knob.addEventListener(event,()=>{drag=null;});
knob.addEventListener('keydown',e=>{let next=speed;if(['ArrowUp','ArrowRight'].includes(e.key))next+=5;else if(['ArrowDown','ArrowLeft'].includes(e.key))next-=5;else if(e.key==='Home')next=0;else if(e.key==='End')next=250;else if(e.key==='PageUp')next+=25;else if(e.key==='PageDown')next-=25;else return;e.preventDefault();setSpeed(next);});
$('increase').addEventListener('click',()=>setSpeed(speed+5));$('decrease').addEventListener('click',()=>setSpeed(speed-5));$('reset').addEventListener('click',reset);
$('engineButton').addEventListener('click',toggleEngine);$('brakeButton').addEventListener('click',toggleBrake);
for(const button of document.querySelectorAll('[data-status]'))button.addEventListener('click',()=>{flags[button.dataset.status]=!flags[button.dataset.status];revision++;render();sync();});
window.simpleDashboard={setSpeed,reset,getState:()=>({...values(),targetSpeed:speed,engineRunning,braking})};
function setView(view){const abs=view==='abs';$('ecuSensors').hidden=abs;$('absSensors').hidden=!abs;$('rpmRow').hidden=abs;$('rearRow').hidden=!abs;$('dutyRow').hidden=!abs;$('electrical').hidden=abs;$('gaugeTitle').textContent=abs?'FRONT WHEEL SPEED':'VEHICLE SPEED';$('ecuTab').setAttribute('aria-pressed',String(!abs));$('absTab').setAttribute('aria-pressed',String(abs));}
$('ecuTab').addEventListener('click',()=>setView('ecu'));$('absTab').addEventListener('click',()=>setView('abs'));
render();sync();setInterval(sync,500);
setInterval(()=>{const now=Date.now();step((now-lastTick)/1000);lastTick=now;},100);

// Guided workflow records browser-generated simulation only.
const channels={speed:['Vehicle speed','km/h',0,250,1],rpm:['Engine speed','rpm',0,15000,100],ect:['ECT','°C',20,100,1],iat:['IAT','°C',30,50,1],map:['MAP','kPa',20,101.3,.1],tps:['TPS','V',.6,3.5,.01],o2:['O₂','V',0,1.2,.01],lambda:['Lambda','',.7,1.2,.01],rear:['Rear wheel speed','km/h',0,250,1],battery:['Battery','V',0,30,.1]};
const history=[],events=[],recorded=[],results=[];let recording=false,sessionStart=new Date().toISOString();
const scenarioInfo={power:['Power check','Observe simulated supply and reference readings. Actual supply measurements are required for a live test.'],crank:['Crank recognition','Start the simulated engine. A live test requires a model-specific crank pattern and observed ECU outputs.'],temperature:['Temperature response','Apply a cold ECT setting, then adjust ECT toward warm. Compare actual ECU interpretation when available.'],load:['Throttle / load response','Adjust TPS and MAP independently. This demo does not measure injection or ignition responses.'],oxygen:['O₂ feedback','Change the O₂ voltage and lambda independently. Actual closed-loop response is unavailable.'],abs:['ABS wheel-speed scenario','Apply different simulated wheel speeds. This does not reproduce hydraulic operation or prove ABS activation.']};
function logEvent(message){events.push({time:new Date().toISOString(),message});if(events.length>500)events.shift();const li=document.createElement('li');li.textContent=new Date().toLocaleTimeString()+' · '+message;$('eventLog').prepend(li);while($('eventLog').children.length>100)$('eventLog').lastChild.remove();}
function setOverride(key,value){const c=channels[key];if(!c||!Number.isFinite(value))return;value=Math.max(c[2],Math.min(c[3],value));if(key==='lambda'){overrides.afr=value*14.7;}else overrides[key]=value;render();}
function refreshInputs(){for(const key of Object.keys(channels).filter(k=>!['speed','rpm'].includes(k))){const active=key==='lambda'?Object.hasOwn(overrides,'afr'):Object.hasOwn(overrides,key);$('enable-'+key).checked=active;$('input-'+key).disabled=!active;const v=key==='lambda'?values().afr/14.7:values()[key];$('input-'+key).value=v;$('value-'+key).textContent=v.toFixed(channels[key][4]<1?2:0)+' '+channels[key][1];}}
for(const [key,c] of Object.entries(channels)){for(const id of ['channelA','channelB']){const option=document.createElement('option');option.value=key;option.textContent=c[0];$(id).append(option);}if(['speed','rpm'].includes(key))continue;const row=document.createElement('div');row.className='input-row';const label=document.createElement('label'),enable=document.createElement('input');enable.type='checkbox';enable.id='enable-'+key;label.append(enable,document.createTextNode(' Override '+c[0]));const output=document.createElement('output');output.id='value-'+key;const input=document.createElement('input');Object.assign(input,{type:'range',min:c[2],max:c[3],step:c[4],id:'input-'+key,disabled:true});input.setAttribute('aria-label',c[0]+' simulated setting');row.append(label,input,output);$('inputControls').append(row);enable.addEventListener('change',()=>{if(enable.checked)setOverride(key,Number(input.value));else delete overrides[key==='lambda'?'afr':key];refreshInputs();render();logEvent(c[0]+' override '+(enable.checked?'enabled':'disabled'));});input.addEventListener('input',()=>{setOverride(key,Number(input.value));output.textContent=Number(input.value).toFixed(2)+' '+c[1];});input.addEventListener('change',()=>logEvent(c[0]+' setting: '+input.value+' '+c[1]));}
$('channelA').value='speed';$('channelB').value='rear';
function updateScenario(){const info=scenarioInfo[$('scenario').value];$('testPurpose').textContent='Purpose: '+info[0];$('testSteps').textContent=info[1];$('testOutcome').textContent='Ready · SIMULATED · actual module response unavailable.';}
function applyScenario(){const name=$('scenario').value;reset();if(name!=='power')toggleEngine();if(name==='temperature')setOverride('ect',20);if(name==='load'){setSpeed(60);setOverride('tps',2.5);setOverride('map',75);}if(name==='oxygen'){setOverride('o2',.9);setOverride('lambda',.85);}if(name==='abs'){setSpeed(60);setOverride('rear',35);}refreshInputs();$('testOutcome').textContent='Demo condition applied. Adjust inputs and record observations; no ECU response is measured.';logEvent('Applied scenario: '+scenarioInfo[name][0]);}
function reportText(){return ['SIMULATED TESTBENCH SESSION — NOT AN ECU / ABS CERTIFICATE','Started: '+sessionStart,'Model: '+($('modelName').value||'Demo / unspecified'),'Technician: '+($('technician').value||'Unspecified'),'Source: browser-generated illustrative data; no connected module measurements.','Calibration: illustrative demo v2; AFR = simulated lambda × 14.7.','Recorded samples: '+recorded.length,'Notes: '+$('reportNotes').value,'','Demonstrations:',...results.map(r=>r.time+' | '+r.name+' | '+r.status+'\nSnapshot: '+JSON.stringify(r.snapshot)),'','Events:',...events.map(e=>e.time+' | '+e.message)].join('\n');}
function csvText(){const keys=['speed','rpm','ect','iat','map','tps','o2','afr','rear','battery','ref1','ref2'];const rows=[['timestamp','source',...keys],...recorded.map(r=>[r.time,'SIMULATED',...keys.map(k=>r.data[k])])];return rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');}
function sample(){if(monitorMode)return;const data=values();history.push({time:Date.now(),data});if(history.length>120)history.shift();if(recording){if(recorded.length>=3600){recording=false;logEvent('Recording stopped: 3600 sample limit reached. Export to save this session.');updateRecording();}else recorded.push({time:new Date().toISOString(),data});}$('recordStatus').textContent=(recording?'Recording simulated data':'Recording stopped')+' · '+recorded.length+' samples / 3600 maximum';refreshInputs();drawHistory();}
function drawHistory(){const canvas=$('historyChart'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,900,320);ctx.font='13px sans-serif';const keys=[$('channelA').value,$('channelB').value],colors=['#66d4f1','#ffbd64'];keys.forEach((key,index)=>{const c=channels[key];ctx.strokeStyle=colors[index];ctx.fillStyle=colors[index];ctx.fillText(c[0]+' ('+c[1]+'): '+c[2]+'–'+c[3],20,22+index*20);ctx.beginPath();history.forEach((r,i)=>{const v=key==='lambda'?r.data.afr/14.7:r.data[key],x=30+i/119*840,y=280-(v-c[2])/(c[3]-c[2])*200;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();});ctx.fillStyle='#acbdd1';ctx.fillText('Oldest → newest · 1 sample / second · separate channel scales',30,310);$('chartLegend').textContent=keys.map(k=>channels[k][0]+' is simulated').join(' · ');}
function updateRecording(){$('recordButton').textContent=recording?'Stop recording':'Start recording';$('recordButton').setAttribute('aria-pressed',String(recording));}
for(const button of document.querySelectorAll('[data-page]'))button.addEventListener('click',()=>{for(const b of document.querySelectorAll('[data-page]')){const active=b===button;b.setAttribute('aria-pressed',String(active));$(b.dataset.page+'Page').hidden=!active;}drawHistory();});
$('scenario').addEventListener('change',updateScenario);$('runTest').addEventListener('click',applyScenario);$('completeTest').addEventListener('click',()=>{const r={time:new Date().toISOString(),name:scenarioInfo[$('scenario').value][0],status:'Demo recorded · Insufficient data for module verdict',snapshot:values()};results.push(r);const card=document.createElement('div');card.className='result-card';card.textContent=r.name+' — '+r.status;$('testResults').prepend(card);$('testOutcome').textContent=r.status;logEvent('Recorded demonstration: '+r.name);});
$('recordButton').addEventListener('click',()=>{recording=!recording;updateRecording();logEvent(recording?'Recording started':'Recording stopped');});
$('exportCsv').addEventListener('click',()=>{if(!recorded.length){$('recordStatus').textContent='Start recording to collect samples before exporting.';return;}const url=URL.createObjectURL(new Blob([csvText()],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='simulated-testbench-'+Date.now()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);logEvent('Exported '+recorded.length+' simulated samples');});
$('printReport').addEventListener('click',()=>{$('printSummary').textContent=reportText();window.print();});
for(const id of ['channelA','channelB'])$(id).addEventListener('change',drawHistory);
for(const id of ['engineButton','brakeButton','reset'])$(id).addEventListener('click',()=>{refreshInputs();logEvent(id==='reset'?'Simulation reset; session records retained':$('engineState').textContent);});
for(const button of document.querySelectorAll('[data-status]'))button.addEventListener('click',()=>logEvent('Simulated indicator '+button.dataset.status+': '+flags[button.dataset.status]));
window.guidedDemo={setOverride,applyScenario,csvText,reportText,getRecords:()=>({history:history.length,recorded:recorded.length,results:[...results]}),sample};
updateScenario();refreshInputs();logEvent('Demo session opened; no testbench connected');sample();setInterval(sample,1000);

let liveEnabled=false,liveBusy=false,liveGeneration=0;const liveRows=[];
const liveCells=['liveIat','liveEct','liveO2','liveMap','liveTps','liveHz','liveSwitch9','liveSwitch10'];
function clearLive(){for(const id of liveCells)$(id).textContent='—';}
function validLive(d){return d&&d.source==='measured_adc'&&Number.isFinite(d.sample_ms)&&Number.isFinite(d.age_ms)&&d.age_ms>=0&&d.age_ms<=2000&&['iat_mv','ect_mv','o2_mv','map_mv','tps_mv'].every(k=>Number.isFinite(d[k])&&d[k]>=0&&d[k]<=3300)&&Number.isFinite(d.rpm_hz)&&d.rpm_hz>=0&&Array.isArray(d.clipped)&&d.clipped.length===5&&d.clipped.every(v=>typeof v==='boolean')&&[d.switch9,d.switch10].every(v=>v===0||v===1);}
async function monitorRequest(enabled){const c=new AbortController(),timer=setTimeout(()=>c.abort(),2500);try{const r=await fetch('/api/monitor',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'enabled='+(enabled?'1':'0'),signal:c.signal});if(!r.ok)throw Error('Updated monitor firmware is required; request failed.');const d=await r.json();if(d.enabled!==enabled)throw Error('Invalid monitor response');}finally{clearTimeout(timer);}}
async function stopLive(){liveEnabled=false;liveGeneration++;clearLive();$('stopMonitor').disabled=false;try{await monitorRequest(false);$('liveState').textContent='Stopped. Acquisition is disabled on the board.';$('stopMonitor').disabled=true;}catch{$('liveState').textContent='Could not confirm board stop. Keep the wiring safe; power-cycle the board to disable acquisition.';}finally{$('startMonitor').disabled=false;}}
async function pollLive(){if(!monitorMode||!liveEnabled||liveBusy)return;liveBusy=true;const generation=liveGeneration,c=new AbortController(),timer=setTimeout(()=>c.abort(),2000);try{const r=await fetch('/api/live',{cache:'no-store',signal:c.signal});if(!r.ok)throw Error('Unavailable');const d=await r.json();if(!validLive(d))throw Error('Invalid or stale');if(generation!==liveGeneration)return;['iat_mv','ect_mv','o2_mv','map_mv','tps_mv'].forEach((key,i)=>$(liveCells[i]).textContent=(d[key]/1000).toFixed(3)+' V'+(d.clipped[i]?' · CLIPPED':''));$('liveHz').textContent=d.rpm_hz.toFixed(1)+' Hz';$('liveSwitch9').textContent=d.switch9?'HIGH':'LOW';$('liveSwitch10').textContent=d.switch10?'HIGH':'LOW';$('liveState').textContent='Measured inputs · updated '+new Date().toLocaleTimeString()+' · ECU response is not measured';if(liveRows.length<1800)liveRows.push({time:new Date().toISOString(),...d});$('liveRecordStatus').textContent=liveRows.length+' live samples / 1800'+(liveRows.length===1800?' · recording limit reached':'');}catch{if(generation===liveGeneration){clearLive();$('liveState').textContent='Readings unavailable, warming up, or connection lost. No stale values shown.';}}finally{clearTimeout(timer);liveBusy=false;}}
function showMonitor(){monitorMode=true;$('monitorPanel').hidden=false;$('demoWorkspace').hidden=true;$('monitorModeButton').setAttribute('aria-pressed','true');$('demoModeButton').setAttribute('aria-pressed','false');$('connection').textContent=onBoard?'ESP32 · INPUT MONITOR':'PREVIEW · NO HARDWARE';$('notice').textContent='Input voltages require protected wiring. This monitor does not control an ECU or testbench.';if(!onBoard){$('startMonitor').disabled=true;$('liveState').textContent='Open the flashed ESP32 dashboard at http://192.168.4.1/ to use actual inputs.';}}
$('monitorModeButton').addEventListener('click',showMonitor);
$('demoModeButton').addEventListener('click',async()=>{if(liveEnabled||!$('stopMonitor').disabled){await stopLive();if(!$('stopMonitor').disabled)return;}monitorMode=false;$('monitorPanel').hidden=true;$('demoWorkspace').hidden=false;$('demoModeButton').setAttribute('aria-pressed','true');$('monitorModeButton').setAttribute('aria-pressed','false');render();});
$('startMonitor').addEventListener('click',async()=>{if(!onBoard)return;if(!$('wiringVerified').checked){$('liveState').textContent='Check the signal interface and voltage levels before enabling readings.';return;}$('startMonitor').disabled=true;$('stopMonitor').disabled=false;$('demoModeButton').disabled=true;try{await monitorRequest(true);liveEnabled=true;liveGeneration++;$('stopMonitor').disabled=false;$('liveState').textContent='Starting; waiting for a full frequency sample.';}catch(e){$('liveState').textContent=e.message;$('startMonitor').disabled=false;$('liveState').textContent+='. Use Stop readings to confirm acquisition is disabled.';}finally{$('demoModeButton').disabled=false;}});
$('stopMonitor').addEventListener('click',stopLive);
function liveCsv(){const keys=['time','source','sample_ms','age_ms','iat_mv','ect_mv','o2_mv','map_mv','tps_mv','rpm_hz','switch9','switch10'];return [keys.join(',')+',iat_clipped,ect_clipped,o2_clipped,map_clipped,tps_clipped',...liveRows.map(r=>keys.map(k=>r[k]).join(',')+','+r.clipped.join(','))].join('\r\n');}
$('exportLive').addEventListener('click',()=>{if(!liveRows.length){$('liveRecordStatus').textContent='No measured samples to export.';return;}const url=URL.createObjectURL(new Blob([liveCsv()],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='measured-inputs-'+Date.now()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
window.liveMonitor={validLive,showMonitor,pollLive,liveCsv};setInterval(pollLive,1000);

